import {weekWindow,defaultWeeklySettings} from "./planificacion-semanal.mjs";
export function createWeeklyUI({api,getState,modal,field,locate,today,escape,refresh,notice,isDemo,setMessage}){let config,runs=[],loading=0;const $=s=>document.querySelector(s);async function load(){const root=$("#weekly-content"),version=++loading;const[c,r]=await Promise.all([api("/weekly/config"),api("/weekly/runs")]);if(root!==$("#weekly-content")||version!==loading)return;config=c;runs=r;render(root);}function render(root){const state=getState(),target=weekWindow(today(),config.weeksAhead);root.innerHTML=`<section class="panel"><h2>Configuración</h2><p><strong>${config.weeksAhead} semanas de antelación</strong> · ${config.capacity} visitas y ${config.minutes} min de intervención por técnico/día.</p><p>Semana objetivo: <strong>${escape(target.start)} al ${escape(target.end)}</strong></p><p>${isDemo?"Demo: generación manual y cambios guardados en este navegador.":config.enabled?"Automática: borrador cada lunes; reintenta los siguientes días si una ejecución falla.":"Generación automática desactivada."}</p><div class="actions"><button data-action="weekly-settings">Cambiar ajustes</button><button data-action="weekly-generate" ${!config.origin?"disabled":""}>Generar borrador semanal</button></div>${!config.origin?"<p>Configura primero el origen, destino y técnicos.</p>":""}</section>${runs.map(run=>{const d=run.payload;return`<section class="panel weekly-run"><h2>${escape(d.weekStart)} al ${escape(d.weekEnd)} <span class="badge">${run.status==="approved"?"Aprobado":"Borrador"}</span></h2><p>${d.assignedCount} visitas propuestas · ${d.preservedCount} citas conservadas · ${d.unassigned.length} pendientes en bolsa.</p><p class="muted">${escape(d.method)}</p>${run.status==="draft"&&d.assignedCount?`<button data-action="weekly-approve" data-id="${run.id}">Revisar y aprobar ${d.assignedCount} visitas</button>`:""}<div class="cards">${d.groups.map(g=>`<article class="card"><h3>${escape(g.day)} · ${escape(state.team.find(t=>t.user_id===g.technicianId)?.name)}</h3><p>${g.existingCount} existentes + ${g.visits.length} propuestas / ${g.capacity}</p><ul>${g.visits.map(v=>`<li>${escape(state.clients.find(c=>c.id===v.clientId)?.data.nombre)} · vence ${escape(v.dueDate)}${v.late?' <strong class="danger">Fuera de plazo</strong>':""}</li>`).join("")}</ul></article>`).join("")}</div>${d.unassigned.length?`<details><summary>Ver ${d.unassigned.length} visitas que siguen en bolsa</summary><ul>${d.unassigned.map(v=>`<li>${escape(state.clients.find(c=>c.id===v.clientId)?.data.nombre)}: ${escape(v.reason)}</li>`).join("")}</ul></details>`:""}${run.status==="approved"?"<p>Las visitas ya están en Agenda. Las propuestas de cita se envían por separado.</p>":""}</section>`;}).join("")||'<p class="empty">Todavía no hay borradores semanales.</p>'}`;}async function action(name,id){if(name==="weekly-settings"){const state=getState(),c=config??defaultWeeklySettings(state.userId),days=[[1,"Lunes"],[2,"Martes"],[3,"Miércoles"],[4,"Jueves"],[5,"Viernes"],[6,"Sábado"],[0,"Domingo"]];modal("Ajustes de planificación semanal",field("weeksAhead","Semanas de antelación (X)",c.weeksAhead,"number")+field("capacity","Máximo de visitas por técnico y día",c.capacity,"number")+field("minutes","Minutos de intervención por técnico y día",c.minutes,"number")+`<fieldset><legend>Días laborables</legend><div class="actions">${days.map(([day,label])=>`<label><input name="weekday-${day}" type="checkbox" ${c.weekdays.includes(day)?"checked":""}>${label}</label>`).join("")}</div></fieldset><label>Técnicos disponibles<select name="weeklyTechnicians" multiple size="${Math.min(5,state.team.length)}">${state.team.map(t=>`<option value="${escape(t.user_id)}" ${c.technicianIds.includes(t.user_id)?"selected":""}>${escape(t.name)}</option>`).join("")}</select></label>`+field("origin","Origen: dirección o latitud, longitud",c.originLabel||(c.origin?`${c.origin[1]},${c.origin[0]}`:"Avenida de Cuba 34, Benalmádena, 29631 Málaga"))+field("destination","Destino (vacío: volver al origen)",c.destinationLabel,"text",false)+`<button id="plan-gps" type="button">Usar mi ubicación como origen</button><label><input name="enabled" type="checkbox" ${c.enabled?"checked":""} ${isDemo?"disabled":""}> Crear borradores automáticamente cada lunes</label><p class="muted">${isDemo?"En la demo no se ejecutan tareas al cerrar la página.":"Solo crea borradores: no asigna citas ni envía mensajes sin aprobación."} Los minutos excluyen desplazamientos.</p>`,async f=>{const technicianIds=[...$("#editor [name=weeklyTechnicians]").selectedOptions].map(o=>o.value),origin=await locate(f.origin,undefined,true),destination=f.destination?await locate(f.destination,undefined,true):origin;await api("/weekly/config",{method:"PUT",body:{enabled:!isDemo&&f.enabled==="on",weeksAhead:Number(f.weeksAhead),capacity:Number(f.capacity),minutes:Number(f.minutes),weekdays:days.filter(([day])=>f[`weekday-${day}`]==="on").map(([day])=>day),technicianIds,origin:origin.point,destination:destination.point,originLabel:f.origin,destinationLabel:f.destination}});setMessage("Ajustes semanales guardados.");});}else if(name==="weekly-generate"){const button=$("[data-action=weekly-generate]");button.disabled=true;try{const r=await api("/weekly/draft",{method:"POST",body:{}});await refresh();notice(`Borrador del ${r.week_start} al ${r.week_end}: ${r.payload.assignedCount} visitas propuestas y ${r.payload.unassigned.length} en bolsa.`);}finally{if(button.isConnected)button.disabled=false;}}else if(name==="weekly-approve"){const run=runs.find(r=>r.id===id);modal("Aprobar borrador semanal",`<p>Se asignarán ${run.payload.assignedCount} visitas entre ${escape(run.week_start)} y ${escape(run.week_end)}. Se conservarán las citas existentes.</p><p>No se enviarán mensajes. Si la agenda ha cambiado, regenera el borrador.</p>`,async()=>{const r=await api(`/weekly/runs/${id}/approve`,{method:"POST",body:{revision:run.revision}});setMessage(`${r.applied} visitas asignadas a la agenda.`);});}else return false;return true;}return{load,action};}
